def compute(vars):
    roe_ratio = vars["v1"]
    roe_percentage = round(roe_ratio * 100, 2)

    return {
        "value": roe_percentage,
        "trace": {
            "v1": roe_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
